import { fetchKulturhusetEvents } from './src/sources/kulturhuset';

async function test() {
  console.log('Testing Kulturhuset start_time output...');
  const events = await fetchKulturhusetEvents({ limit: 3 });
  console.log(`Found ${events.length} events`);
  events.forEach((ev, i) => {
    console.log(`\nEvent ${i+1}:`);
    console.log(`  date: ${ev.date}`);
    console.log(`  time: ${ev.time}`);
    console.log(`  start_time: ${ev.start_time}`);
  });
}
test().catch(console.error);
EOF
